begin;
set local search_path=public,extensions;
grant usage on schema extensions to authenticated,service_role;
select no_plan();
-- Synthetic financial approvals only. Nothing is seeded into a real deployment.
update private.admin_execution_environment_v1 set environment='DEVELOPMENT',configuration_reference='TEST-251-TRUSTED-LOCAL',configured_at=clock_timestamp()where singleton;
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)select('a2510000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','manual-credits251-'||i||'@example.invalid','',now(),'{}','{}',now(),now()from generate_series(1,4)i;
insert into public.platform_user_roles(user_id,role_code)select('a2510000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'FINANCE_MANAGER'from generate_series(1,3)i;
insert into public.organizations(id,legal_name,display_name,status,created_by)values('b2510000-0000-4000-8000-000000000001','TEST manual251','TEST manual251','ACTIVE','a2510000-0000-4000-8000-000000000001'),('b2510000-0000-4000-8000-000000000002','TEST foreign251','TEST foreign251','ACTIVE','a2510000-0000-4000-8000-000000000001');
insert into public.credit_wallets(id,organization_id,wallet_type)values('c2510000-0000-4000-8000-000000000001','b2510000-0000-4000-8000-000000000001','CLIENT'),('c2510000-0000-4000-8000-000000000002','b2510000-0000-4000-8000-000000000002','CLIENT');
create temporary table manual251(k text primary key,v jsonb);grant all on manual251 to authenticated;
create function pg_temp.actor251(p_i integer,p_aal text default'aal2')returns void language plpgsql as $$declare uid text:='a2510000-0000-4000-8000-'||lpad(p_i::text,12,'0');begin perform set_config('request.jwt.claim.sub',uid,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated','aal',p_aal)::text,true);end$$;
create function pg_temp.request251(p_key text,p_quantity bigint default 13)returns jsonb language sql as $$select public.request_manual_credit_grant_v1('b2510000-0000-4000-8000-000000000001','c2510000-0000-4000-8000-000000000001','ADMIN_GRANT',p_quantity,'2099-01-01T12:00:00Z',null,'TEST-251-GIFT','TEST synthetic gift, reviewed by an independent Finance actor',p_key)$$;
select ok(not has_function_privilege('authenticated','private.issue_credits_authorized_core_v1(uuid,uuid,text,bigint,timestamptz,uuid,text,bigint,text,text,text,uuid)','execute')and not has_function_privilege('service_role','private.issue_credits_authorized_core_v1(uuid,uuid,text,bigint,timestamptz,uuid,text,bigint,text,text,text,uuid)','execute'),'the shared authoritative core is not an API surface');
select ok(not has_table_privilege('authenticated','public.manual_credit_grant_requests_v1','insert')and not has_table_privilege('authenticated','public.manual_credit_grant_reviews_v1','update'),'direct financial request/review writes are unavailable');
set local role authenticated;select pg_temp.actor251(1,'aal1');
select throws_ok($$select pg_temp.request251('TEST-251-AAL1')$$,'42501','MANUAL_CREDIT_FINANCE_AAL2_REQUIRED','Finance AAL1 cannot request a gift');
select pg_temp.actor251(4);
select throws_ok($$select pg_temp.request251('TEST-251-outsider')$$,'42501','MANUAL_CREDIT_FINANCE_AAL2_REQUIRED','an ordinary account cannot request a gift');
select pg_temp.actor251(1);
select throws_ok($$select public.issue_credits('b2510000-0000-4000-8000-000000000001','c2510000-0000-4000-8000-000000000001','ADMIN_GRANT',13,'2099-01-01',null,'TEST',0,'TEST','APPROVED','TEST-251-free-text')$$,'55000','CREDIT_MANUAL_GOVERNED_REQUEST_REQUIRED','a free approval string cannot issue manual credits');
select throws_ok($$select public.issue_credits('b2510000-0000-4000-8000-000000000001','c2510000-0000-4000-8000-000000000001','BONUS',13,'2099-01-01',null,'REWARD_EVENT:aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',0,'TEST','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','TEST-251-fake-reward')$$,'55000','CREDIT_MANUAL_GOVERNED_REQUEST_REQUIRED','a fabricated native reward reference cannot bypass the reward engine');
select throws_ok($$select public.issue_credits('b2510000-0000-4000-8000-000000000001','c2510000-0000-4000-8000-000000000001','EXTRA_PURCHASE',13,'2099-01-01',null,'TEST payment reference',999,'TEST',null,'TEST-251-fake-pack')$$,'55000','CREDIT_PACK_CANONICAL_PAYMENT_REQUIRED','a free pack payment reference cannot fabricate paid credit revenue');
select throws_ok($$select public.issue_credits('b2510000-0000-4000-8000-000000000001','c2510000-0000-4000-8000-000000000001','SUBSCRIPTION_GRANT',13,'2099-01-01',null,'TEST payment reference',0,'TEST',null,'TEST-251-fake-subscription')$$,'55000','CREDIT_SUBSCRIPTION_PAYMENT_SOURCE_REQUIRED','canonical funding triggers reject a fabricated subscription source');
insert into manual251 values('request',pg_temp.request251('TEST-251-request',9007199254740993)),('replay',pg_temp.request251('TEST-251-request',9007199254740993));
select is((select v->>'request_id'from manual251 where k='request'),(select v->>'request_id'from manual251 where k='replay'),'request retry preserves one immutable authorization');
select throws_ok($$select pg_temp.request251('TEST-251-request',14)$$,'22023','IDEMPOTENCY_KEY_REUSED','the same command key cannot change its frozen quantity');
select throws_ok($$select public.request_manual_credit_grant_v1('b2510000-0000-4000-8000-000000000001','c2510000-0000-4000-8000-000000000002','ADMIN_GRANT',1,'2099-01-01',null,'TEST','TEST cross-tenant wallet mismatch','TEST-251-foreign')$$,'23514','MANUAL_CREDIT_CLIENT_WALLET_REQUIRED','the wallet must belong to the exact requested organization');
select throws_ok($$select public.review_manual_credit_grant_v1((select(v->>'request_id')::uuid from manual251 where k='request'),(select v->>'content_hash'from manual251 where k='request'),true,true,'TEST-251-APPROVAL','TEST self approval is denied')$$,'42501','MANUAL_CREDIT_INDEPENDENT_FINANCE_REVIEW_REQUIRED','the requester cannot approve their own gift');
select pg_temp.actor251(2);
select throws_ok($$select public.review_manual_credit_grant_v1((select(v->>'request_id')::uuid from manual251 where k='request'),repeat('f',64),true,true,'TEST-251-APPROVAL','TEST stale terms must not approve')$$,'40001','STALE_MANUAL_CREDIT_REQUEST','a stale hash cannot approve different terms');
select throws_ok($$select public.review_manual_credit_grant_v1((select(v->>'request_id')::uuid from manual251 where k='request'),(select v->>'content_hash'from manual251 where k='request'),true,false,'TEST-251-APPROVAL','TEST explicit review is required')$$,'22023','MANUAL_CREDIT_DOCUMENTED_REVIEW_REQUIRED','approval needs explicit review confirmation');
insert into manual251 values('review',public.review_manual_credit_grant_v1((select(v->>'request_id')::uuid from manual251 where k='request'),(select v->>'content_hash'from manual251 where k='request'),true,true,'TEST-251-APPROVAL','TEST independent review of this exact synthetic gift'));
reset role;
select is((select count(*)from public.credit_lots where organization_id='b2510000-0000-4000-8000-000000000001'),0::bigint,'approval alone never creates a financial lot');
update public.platform_user_roles set revoked_at=clock_timestamp()where user_id='a2510000-0000-4000-8000-000000000002';
set local role authenticated;select pg_temp.actor251(3);
select throws_ok($$select public.execute_manual_credit_grant_v1((select(v->>'request_id')::uuid from manual251 where k='request'),(select v->>'content_hash'from manual251 where k='request'),(select v->>'review_proof_hash'from manual251 where k='review'),'TEST-251-exec-revoked')$$,'42501','MANUAL_CREDIT_CURRENT_AUTHORITIES_REQUIRED','a revoked reviewer cannot authorize a new execution');
reset role;update public.platform_user_roles set revoked_at=null where user_id='a2510000-0000-4000-8000-000000000002';
update private.admin_execution_environment_v1 set environment='PRODUCTION'where singleton;
set local role authenticated;
select throws_ok($$select public.execute_manual_credit_grant_v1((select(v->>'request_id')::uuid from manual251 where k='request'),(select v->>'content_hash'from manual251 where k='request'),(select v->>'review_proof_hash'from manual251 where k='review'),'TEST-251-exec-prod')$$,'55000','MANUAL_CREDIT_ENVIRONMENT_MISMATCH','a trusted environment change prevents a differently approved financial effect');
reset role;update private.admin_execution_environment_v1 set environment='DEVELOPMENT'where singleton;
set local role authenticated;
insert into manual251 values('execute',public.execute_manual_credit_grant_v1((select(v->>'request_id')::uuid from manual251 where k='request'),(select v->>'content_hash'from manual251 where k='request'),(select v->>'review_proof_hash'from manual251 where k='review'),'TEST-251-exec-first'));
insert into manual251 values('execute-new-key',public.execute_manual_credit_grant_v1((select(v->>'request_id')::uuid from manual251 where k='request'),(select v->>'content_hash'from manual251 where k='request'),(select v->>'review_proof_hash'from manual251 where k='review'),'TEST-251-exec-second'));
reset role;
select is((select v->>'credit_lot_id'from manual251 where k='execute'),(select v->>'credit_lot_id'from manual251 where k='execute-new-key'),'a different key never executes the same approved request twice');
select is((select count(*)from public.credit_lots where organization_id='b2510000-0000-4000-8000-000000000001'),1::bigint,'the approved gift creates exactly one immutable lot');
select is((select quantity::text from public.credit_lots where id=(select(v->>'credit_lot_id')::uuid from manual251 where k='execute')),'9007199254740993','the executed quantity is exact beyond JavaScript safe integers');
select is((select revenue_value_minor from public.credit_lots where id=(select(v->>'credit_lot_id')::uuid from manual251 where k='execute')),0::bigint,'a gift does not fabricate subscription or cash revenue');
select is((select count(*)from public.event_outbox where event_type='ManualCreditGrantExecutedV1'and aggregate_id=(select v->>'request_id'from manual251 where k='request')),1::bigint,'the execution fact is emitted exactly once');
select throws_ok($$update public.manual_credit_grant_requests_v1 set quantity=1 where id=(select(v->>'request_id')::uuid from manual251 where k='request')$$,'55000','CLIENT_HISTORY_IMMUTABLE','approved request terms remain immutable');
-- Native automatic rewards preserve their real source/rule/review/cap engine.
insert into public.client_projects(id,organization_id,project_code,status,created_by)values('d2511000-0000-4000-8000-000000000001','b2510000-0000-4000-8000-000000000001','TEST_REWARD_251','ACTIVE','a2510000-0000-4000-8000-000000000001');
insert into public.reward_rule_versions(id,rule_code,version_number,status,trigger_event,audience_type,bonus_credits,per_recipient_cap_credits,global_cap_credits,window_days,cooldown_hours,credit_validity_days,eligibility_rule,requires_approval,effective_from,content_hash,change_reason,created_by)values('d2511000-0000-4000-8000-000000000002','TEST_REWARD251',1,'ACTIVE','PROJECT_COMPLETED','CLIENT_ORGANIZATION',25,50,500,30,0,90,'{"completed":true}',true,clock_timestamp()-interval'1 day',repeat('a',64),'TEST synthetic native reward policy','a2510000-0000-4000-8000-000000000001');
set local role authenticated;select pg_temp.actor251(1);
insert into manual251 values('reward-source',public.record_reward_source_event('b2510000-0000-4000-8000-000000000001','PROJECT_COMPLETED','CLIENT_ORGANIZATION','CLIENT_PROJECT','d2511000-0000-4000-8000-000000000001','{"completed":true}','["TEST project completion proof251"]',repeat('b',64),clock_timestamp(),'TEST-251-reward-source'));
select pg_temp.actor251(2);
insert into manual251 values('reward-review',public.decide_reward_award((select(v->>'source_event_id')::uuid from manual251 where k='reward-source'),'d2511000-0000-4000-8000-000000000002','APPROVED','TEST independent source and native rule review','TEST-251-reward-review'));
select pg_temp.actor251(1);
insert into manual251 values('reward',public.award_reward('b2510000-0000-4000-8000-000000000001','c2510000-0000-4000-8000-000000000001','d2511000-0000-4000-8000-000000000002','CLIENT_PROJECT','d2511000-0000-4000-8000-000000000001',repeat('c',64),jsonb_build_object('source_event_id',(select v->>'source_event_id'from manual251 where k='reward-source')),(select v->>'approval_id'from manual251 where k='reward-review'),'TEST-251-native-reward'));
reset role;
select is((select v->>'outcome'from manual251 where k='reward'),'REWARD_GRANTED','the genuinely approved native reward still executes through its private authoritative core');
select is((select quantity from public.credit_lots where id=(select(v->>'credit_lot_id')::uuid from manual251 where k='reward')),25::bigint,'native reward quantity comes from its approved rule rather than free credit inputs');
select*from finish();rollback;
